package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Both() {
        Complex c = Complex.NaN;
        Complex divisor = new Complex(1.0, 1.0);
        Complex result = c.divide(divisor);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_Divisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = Complex.NaN;
        Complex result = c.divide(divisor);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = Complex.ZERO;
        Complex result = c.divide(divisor);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteDividend() {
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = Complex.INF;
        Complex result = c.divide(divisor);
        assertTrue(result.equals(Complex.ZERO));
    }

    @Test
    public void testDivide_InfiniteDivisor_InfiniteDividend() {
        // If both are infinite, the code proceeds to the calculation logic
        // This branch is implicitly covered by the logic below
        Complex c = Complex.INF;
        Complex divisor = Complex.INF;
        Complex result = c.divide(divisor);
        // result will be calculated via the branches
        assertNotNull(result);
    }

    @Test
    public void testDivide_Branch_RealLessThanImaginary() {
        // c = 1, d = 2 -> |c| < |d|
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 2.0);
        // (1+i) / (1+2i) = [(1+i)(1-2i)] / [1^2 + 2^2] = (1 - 2i + i + 2) / 5 = (3 - i) / 5 = 0.6 - 0.2i
        Complex result = c.divide(divisor);
        assertEquals(0.6, result.getReal(), EPSILON);
        assertEquals(-0.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_RealGreaterThanImaginary() {
        // c = 2, d = 1 -> |c| >= |d|
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(2.0, 1.0);
        // (1+i) / (2+i) = [(1+i)(2-i)] / [2^2 + 1^2] = (2 - i + 2i + 1) / 5 = (3 + i) / 5 = 0.6 + 0.2i
        Complex result = c.divide(divisor);
        assertEquals(0.6, result.getReal(), EPSILON);
        assertEquals(0.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_RealEqualsImaginary() {
        // c = 1, d = 1 -> |c| is not < |d| (goes to else branch)
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 1.0);
        // (1+i) / (1+i) = 1
        Complex result = c.divide(divisor);
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_NegativeValues() {
        Complex c = new Complex(-1.0, -1.0);
        Complex divisor = new Complex(2.0, -1.0);
        // (-1-i) / (2-i) = [(-1-i)(2+i)] / 5 = (-2 - i - 2i + 1) / 5 = (-1 - 3i) / 5 = -0.2 - 0.6i
        Complex result = c.divide(divisor);
        assertEquals(-0.2, result.getReal(), EPSILON);
        assertEquals(-0.6, result.getImaginary(), EPSILON);
    }
}
